ON CONFLICT DO NOTHING;

DO $post$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM site_work_items
   WHERE created_by='brochure_contrast_front_thread' AND item_type='content_rewrite';
  IF n < 23 THEN RAISE EXCEPTION 'post: expected at least 23 rewrite items, found %', n; END IF;
  SELECT count(*) INTO n FROM site_work_items
   WHERE created_by='brochure_contrast_front_thread' AND item_type='content_rewrite'
     AND spec->>'suggestion' NOT LIKE '%must survive in full%';
  IF n <> 0 THEN RAISE EXCEPTION 'post: % item(s) missing the caveat-protection clause', n; END IF;
  SELECT count(*) INTO n FROM site_work_items
   WHERE created_by='brochure_contrast_front_thread' AND item_type='content_rewrite'
     AND spec->>'suggestion' NOT LIKE '%CHANGE NOTHING%';
  IF n > 2 THEN RAISE EXCEPTION 'post: % item(s) missing the leave-good-copy-alone clause (2 canaries predate it)', n; END IF;
END $post$;

SELECT count(*) AS total_rewrite_items, count(*) FILTER (WHERE status='triaged') AS triaged
  FROM site_work_items WHERE created_by='brochure_contrast_front_thread' AND item_type='content_rewrite';

COMMIT;
